<script setup>
import { computed, onMounted, ref } from 'vue';
import { $http } from '@/plugins/axios';
import UiModal from '@/components/ui/Modal.vue';
const owners = ref([]), labs = ref([]), loading = ref(false), saving = ref(false), error = ref(''), formError = ref('');
const search = ref(''), page = ref(1), last = ref(1), modal = ref(false), labSearch = ref(''), form = ref({});
const filteredLabs = computed(() => labs.value.filter(l => l.name.toLowerCase().includes(labSearch.value.toLowerCase())));
const errorText = e => Object.values(e.response?.data?.errors || {}).flat()[0] || e.response?.data?.message || 'تعذر تنفيذ العملية.';
async function load() {
  loading.value = true; error.value = '';
  try { const { data } = await $http.get('/super-admin/owners', { params:{ search:search.value, page:page.value } }); owners.value = data.owners.data; last.value = data.owners.last_page; labs.value = data.labs; }
  catch(e) { error.value = errorText(e); } finally { loading.value = false; }
}
function edit(owner = {}) { form.value = { id:owner.id, name:owner.name || '', email:owner.email || '', password:'', phone_number:owner.phone_number || '', status:owner.status ?? 1, lab_ids:[...(owner.lab_ids || [])] }; formError.value = ''; labSearch.value = ''; modal.value = true; }
async function save() {
  saving.value = true; formError.value = '';
  try { const payload = { ...form.value }; delete payload.id; if (!payload.password) delete payload.password;
    await $http[form.value.id ? 'put' : 'post']('/super-admin/owners' + (form.value.id ? `/${form.value.id}` : ''), payload);
    modal.value = false; await load();
  } catch(e) { formError.value = errorText(e); } finally { saving.value = false; }
}
onMounted(load);
</script>
<template>
  <section dir="rtl" class="owners-admin">
    <header><div><p>DIGITAL LAB · ADMINISTRATION</p><h1>حسابات المالكين</h1><span>حساب واحد لمتابعة عدة مختبرات من بوابة خاصة.</span></div><button @click="edit()">＋ إنشاء حساب مالك</button></header>
    <div class="owners-info"><i class="pi pi-shield"></i><p>حدد المختبرات التي يحق لكل مالك متابعتها. يستطيع المالك مراجعة التقارير والرقابة وإدارة موظفي المختبرات المرتبطة به. إضافة المختبرات للحساب تتم من هذه الصفحة.</p></div>
    <form class="owners-search" @submit.prevent="page = 1; load()"><input v-model="search" placeholder="ابحث باسم المالك أو البريد الإلكتروني" aria-label="البحث عن مالك"><button>بحث</button></form>
    <p v-if="error" class="owners-error" role="alert">{{ error }}</p><p v-if="loading" role="status">جاري التحميل...</p>
    <div v-else class="owners-grid"><article v-for="owner in owners" :key="owner.id"><div class="owners-avatar">{{ owner.name.slice(0,1) }}</div><div><h2>{{ owner.name }}</h2><small dir="ltr">{{ owner.email }}</small></div><span :class="['owners-status', { off:!owner.status }]">{{ owner.status ? 'فعال' : 'معطل' }}</span><div class="owners-labs"><span v-for="id in owner.lab_ids" :key="id">{{ labs.find(l => l.id === Number(id))?.name || `#${id}` }}</span><small v-if="!owner.lab_ids.length">لم يتم ربط مختبرات بعد</small></div><button class="owners-edit" @click="edit(owner)">إدارة الحساب والمختبرات</button></article><p v-if="!owners.length">لا توجد حسابات مالكين مطابقة.</p></div>
    <div v-if="last > 1" class="owners-pager"><button :disabled="page === 1" @click="page--; load()">السابق</button><span>{{ page }} / {{ last }}</span><button :disabled="page === last" @click="page++; load()">التالي</button></div>
    <UiModal v-model="modal" size="lg"><template #header><h2>{{ form.id ? 'إدارة حساب المالك' : 'إنشاء حساب مالك' }}</h2></template><form @submit.prevent="save" class="owners-form" dir="rtl"><p v-if="formError" role="alert" class="owners-error">{{ formError }}</p><label>الاسم الكامل<input v-model="form.name" required maxlength="150"></label><label>البريد الإلكتروني<input v-model="form.email" type="email" required dir="ltr" autocomplete="off"></label><label>رقم الهاتف<input v-model="form.phone_number" maxlength="30" dir="ltr"></label><label>{{ form.id ? 'كلمة مرور جديدة (اختياري)' : 'كلمة المرور' }}<input v-model="form.password" type="password" :required="!form.id" minlength="10" maxlength="128" autocomplete="new-password"></label><label>حالة الحساب<select v-model.number="form.status"><option :value="1">فعال</option><option :value="0">معطل</option></select></label><fieldset><legend>المختبرات المرتبطة ({{ form.lab_ids.length }})</legend><input v-model="labSearch" placeholder="ابحث عن مختبر" aria-label="البحث عن مختبر للربط"><div class="owners-lab-options"><label v-for="lab in filteredLabs" :key="lab.id"><input v-model="form.lab_ids" type="checkbox" :value="lab.id"><span>{{ lab.name }}</span><small v-if="!lab.status">معطل</small></label><p v-if="!filteredLabs.length">لا توجد مختبرات مطابقة.</p></div></fieldset><p class="owners-help">يدخل المالك من صفحة تسجيل الدخول المعتادة، ثم ينتقل تلقائياً إلى بوابته. إعادة تعيين كلمة المرور أو تعطيل الحساب تنهي جلساته الحالية.</p><button :disabled="saving">{{ saving ? 'جاري الحفظ...' : 'حفظ حساب المالك' }}</button></form></UiModal>
  </section>
</template>
<style scoped>
.owners-admin{color:#25473e}.owners-admin header{display:flex;justify-content:space-between;align-items:center;gap:18px;margin:12px 0 24px}.owners-admin header p{font-size:9px;letter-spacing:2px;color:#81a195}.owners-admin h1{font-size:28px;font-weight:800;margin:7px 0}.owners-admin header span{font-size:12px;color:#83958c}.owners-admin button{border-radius:10px;background:#226f54;color:white;padding:12px 20px;border:0;font-size:12px;cursor:pointer}.owners-admin button:disabled{opacity:.5}.owners-info{display:flex;gap:13px;padding:20px;background:#ecf6ee;border:1px solid #dcebdd;border-radius:14px;font-size:12px;line-height:1.9;color:#63846c}.owners-info i{margin-top:5px}.owners-search{display:flex;gap:10px;margin:22px 0}.owners-search input{flex:1}.owners-admin input,.owners-admin select{padding:11px 13px;border:1px solid #dce6df;border-radius:9px;font-size:12px;min-width:0;background:white}.owners-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}.owners-grid article{background:white;border:1px solid #e0e8e0;border-radius:18px;padding:23px;display:flex;gap:14px;align-items:center;flex-wrap:wrap}.owners-avatar{width:40px;height:40px;display:grid;place-items:center;background:#edf4e9;color:#5f8b4e;border-radius:50%;font-weight:bold}.owners-grid h2{font-weight:750;font-size:15px}.owners-grid small{color:#8a9e7c;font-size:10px;overflow-wrap:anywhere}.owners-status{padding:4px 9px;border-radius:6px;background:#edf8eb;color:#53863f;margin-right:auto;font-size:10px}.owners-status.off{background:#fdefeb;color:#b87263}.owners-labs{display:flex;gap:7px;flex-wrap:wrap;width:100%;padding:10px 0}.owners-labs span{padding:6px 10px;border-radius:7px;background:#f2f5ef;font-size:10px;color:#7f926b}.owners-grid .owners-edit{width:100%;border:1px solid #dbe6d2;background:#f8faf6;color:#57713e}.owners-pager{display:flex;gap:20px;align-items:center;justify-content:center;margin:22px 0}.owners-form{padding:24px;display:grid;gap:17px}.owners-form>label{display:gr